#!/bin/bashecho "========================================"echo "AI Resume & Job Matching System Backend"echo "========================================"echo ""# Check if virtual environment existsif [ ! -d "venv" ]; then    echo "Creating virtual environment..."    python3 -m venv venv    echo ""fi# Activate virtual environmentecho "Activating virtual environment..."source venv/bin/activateecho ""# Check if requirements are installedif [ ! -d "venv/lib/python3.9/site-packages/fastapi" ] && [ ! -d "venv/lib/python3.10/site-packages/fastapi" ] && [ ! -d "venv/lib/python3.11/site-packages/fastapi" ]; then    echo "Installing dependencies..."    pip install -r requirements.txt    echo ""fi# Check if .env file existsif [ ! -f ".env" ]; then    echo "WARNING: .env file not found!"    echo "Please copy .env.example to .env and add your Gemini API key"    echo ""    exit 1fi# Start the serverecho "Starting FastAPI server..."echo "Backend will be available at: http://localhost:8000"echo "API Documentation: http://localhost:8000/docs"echo ""echo "Press Ctrl+C to stop the server"echo ""python -m uvicorn app.main:app --host 0.0.0.0 --port 8000 --reload# Made with Bob